struct MatchPost {
    post: Expr,
    name: Path,
    arms: Vec<Arm>,
    label: Option<Expr>,
}

struct MatchPrePost {
    pre: Expr,
    post: Expr,
    name: Path,
    arms: Vec<Arm>,
    label: Option<Expr>,
}

struct Arm {
    step_name: Ident,
    params: Vec<Ident>,
    block: ExprBlock,
}

impl Parse for MatchPost {
    fn parse(input: ParseStream) -> parse::Result<MatchPost> {
        let post: Expr = input.parse()?;
        let _: Token![,] = input.parse()?;

        let next_arg: Expr = input.parse()?;

